class NegativeError(Exception):
    pass
def process(n):
    if n < 0: raise NegativeError(f"{n} is negative!")
try:
    process(-5)
except NegativeError as e:
    print(f"Custom error: {e}")

def read_number(filename):
    try:
        with open(filename) as f:
            return float(f.read().strip())
    except FileNotFoundError:
        print("File missing")
    except ValueError:
        print("Not a number")
    return None
print(read_number("data.txt"))

def calc(a, b, op):
    try:
        a, b = float(a), float(b)
        if op == "+": return a+b
        elif op == "-": return a-b
        elif op == "*": return a*b
        elif op == "/":
            if b==0: raise ZeroDivisionError
            return a/b
        else: raise ValueError(f"Unknown op: {op}")
    except (ValueError, ZeroDivisionError) as e:
        return f"Error: {e}"
print(calc(10, 5, "+"))
print(calc(10, 0, "/"))

import random
class InvalidReadingError(Exception):
    pass
def read_sensor():
    val = random.uniform(-10, 50)
    if val < 0 or val > 40: raise InvalidReadingError(f"Invalid reading: {val}")
    return val
readings = []
for i in range(10):
    try:
        r = read_sensor()
        readings.append(r)
        print(f"Reading {i+1}: {r:.2f}")
    except InvalidReadingError as e: print(f"Error: {e}")
if readings: print(f"Valid readings: {len(readings)}/10")

